<script setup>
import {computed,ref} from 'vue';import {matchShade,whitenessIndex} from '../engines/vitaShadeCiede2000Engine.js';
const emit=defineEmits(['save']);const rgb=ref({r:214,g:191,b:158});const presets=[{name:'Natural A1-like',r:220,g:202,b:172},{name:'Warm A3-like',r:188,g:153,b:113},{name:'Bright 0M2-like',r:239,g:224,b:198},{name:'Cool C4-like',r:157,g:143,b:127}];const corrected=computed(()=>({L:Math.round((rgb.value.r*.2126+rgb.value.g*.7152+rgb.value.b*.0722)/255*100),a:Math.round((rgb.value.r-rgb.value.g)/8),b:Math.round((rgb.value.g-rgb.value.b)/5)}));const match=computed(()=>matchShade(corrected.value));const wi=computed(()=>whitenessIndex(corrected.value));
</script>
<template><section class="module-card glass"><div class="module-head"><div><div class="eyebrow">04 / Shade exploration & color science</div><h2>VITA shade colorimeter</h2><p>Adjust a sample RGB color and compare it against a compact illustrative shade library. Screen color, exposure, white balance, and ambient light make this unsuitable for clinical shade matching.</p></div><span class="badge">D65 REFERENCE · SIMULATED</span></div><div class="two-col"><div><div class="inner"><h3>Choose a sample</h3><div class="preset-list"><button v-for="p in presets" :key="p.name" class="preset" @click="rgb={r:p.r,g:p.g,b:p.b}">{{p.name}}</button></div><div class="control-row" v-for="key in ['r','g','b']" :key="key"><span class="small">{{key.toUpperCase()}} channel</span><b>{{rgb[key]}}</b></div><input v-for="key in ['r','g','b']" :key="key+'slider'" class="range" type="range" min="0" max="255" v-model.number="rgb[key]"><div class="control-row"><span class="small">Sample swatch</span><span class="shade-chip" :style="{background:`rgb(${rgb.r},${rgb.g},${rgb.b})`,width:'42px',height:'30px'}"></span></div></div><div class="inner" style="margin-top:12px"><h3>3-zone concept</h3><div class="three-zones"><div v-for="(zone,i) in ['Cervical','Middle','Incisal']" :key="zone" :style="{background:`rgba(${rgb.r-i*10},${rgb.g-i*6},${rgb.b-i*3},${.94-i*.1})`}"><span>{{zone}}</span></div></div></div></div><div><div class="inner"><h3>Illustrative nearest match</h3><div class="shade-result"><span class="shade-chip" :style="{background:`rgb(${Math.max(0,220-match.b*2)},${Math.max(0,215-match.a*4)},${Math.max(0,205-match.b*4)})`,width:'54px',height:'54px'}"></span><div><div class="eyebrow">{{match.name}}</div><div class="small">Color distance ΔE₀₀ ≈ {{match.deltaE}}</div></div></div><div class="metric-grid"><div class="metric"><span>L*</span><b>{{corrected.L}}</b></div><div class="metric"><span>a*</span><b>{{corrected.a}}</b></div><div class="metric"><span>b*</span><b>{{corrected.b}}</b></div></div><div class="risk"><strong>Whiteness index · {{wi}}</strong><p>Reference comparison is illustrative and cannot guide whitening or restorative treatment.</p></div><button class="action" style="margin-top:12px" @click="emit('save',{module:'vita_shade_records',lab:corrected,match:match.name,deltaE:match.deltaE,whiteness:wi})">Save color sample</button></div><p class="footnote" style="margin-top:12px">Clinical shade matching requires standardized illumination, calibration, and dental equipment. Do not use this tool to select treatment.</p></div></div></section></template>
<style scoped>.three-zones{display:grid;grid-template-columns:repeat(3,1fr);height:88px;border-radius:12px;overflow:hidden}.three-zones div{display:grid;place-items:end center;padding:7px;color:#3e352c;font-size:8px}.shade-result{display:flex;align-items:center;gap:12px;padding:14px 0}.shade-result .shade-chip{margin:0}</style>
